#include "gramschmidt.h"

extern "C" {

void kernel_gramschmidt(
    double A[M + 0][N + 0],
    double R[N + 0][N + 0],
    double Q[M + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=R offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=Q offset=slave bundle=gmem2
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=R bundle=control
#pragma HLS INTERFACE s_axilite port=Q bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local buffers for tiling / parallel access
    double A_local[M][N];
    double R_local[N][N];
    double Q_local[M][N];

#pragma HLS ARRAY_PARTITION variable=A_local cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=Q_local cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=R_local cyclic factor=8 dim=2

    // Load A into local buffer
    load_A_outer: for (int i = 0; i < M; i++) {
        load_A_inner: for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            A_local[i][j] = A[i][j];
        }
    }

    const int m = M;
    const int n = N;

    int i, j, k;
    double nrm;

    for (k = 0; k < n; k++) {
        // Compute norm
        nrm = 0.0;
        norm_loop: for (i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
            nrm += A_local[i][k] * A_local[i][k];
        }
        R_local[k][k] = sqrt(nrm);

        // Compute Q column
        q_loop: for (i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
            Q_local[i][k] = A_local[i][k] / R_local[k][k];
        }

        // Update R and A
        for (j = k + 1; j < n; j++) {
            R_local[k][j] = 0.0;
            r_accum_loop: for (i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
                R_local[k][j] += Q_local[i][k] * A_local[i][j];
            }
            a_update_loop: for (i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
                A_local[i][j] = A_local[i][j] - Q_local[i][k] * R_local[k][j];
            }
        }
    }

    // Write back A
    store_A_outer: for (int i = 0; i < M; i++) {
        store_A_inner: for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            A[i][j] = A_local[i][j];
        }
    }

    // Write back R
    store_R_outer: for (int i = 0; i < N; i++) {
        store_R_inner: for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            R[i][j] = R_local[i][j];
        }
    }

    // Write back Q
    store_Q_outer: for (int i = 0; i < M; i++) {
        store_Q_inner: for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            Q[i][j] = Q_local[i][j];
        }
    }
}

} // extern "C"
