Looking at the current code, it already has local buffers (`A_local`, `R_local`, `Q_local`) but they store the **entire** arrays. True tiling means processing the data in **chunks/tiles** along a dimension, creating smaller local buffers and processing piece by piece.

For Gram-Schmidt, the natural tiling dimension is along rows (the `M` dimension). We tile the `M` rows into chunks of `TILE_M`, so each tile holds a `TILE_M × N` strip of A and Q. The compute phase processes each tile, accumulating contributions to R and updating A.

The key structural change:
- Local buffers shrink from `[M][N]` to `[TILE_M][N]`
- We loop over tiles in the outer loop
- Load/compute/store phases operate on tiles

```cpp
#include "gramschmidt.h"
#include <cmath>

#define TILE_M 16

// Load a tile of A rows [row_start, row_start+TILE_M) into local buffer
static void load_A_tile(double A_global[M][N], double A_local[TILE_M][N], int row_start) {
    for (int i = 0; i < TILE_M; i++) {
#pragma HLS PIPELINE II=1
        for (int j = 0; j < N; j++) {
            int gi = row_start + i;
            A_local[i][j] = (gi < M) ? A_global[gi][j] : 0.0;
        }
    }
}

// Store a tile of A back to global memory
static void store_A_tile(double A_global[M][N], double A_local[TILE_M][N], int row_start) {
    for (int i = 0; i < TILE_M; i++) {
#pragma HLS PIPELINE II=1
        for (int j = 0; j < N; j++) {
            int gi = row_start + i;
            if (gi < M) A_global[gi][j] = A_local[i][j];
        }
    }
}

// Load a tile of Q rows [row_start, row_start+TILE_M) into local buffer
static void load_Q_tile(double Q_global[M][N], double Q_local[TILE_M][N], int row_start) {
    for (int i = 0; i < TILE_M; i++) {
#pragma HLS PIPELINE II=1
        for (int j = 0; j < N; j++) {
            int gi = row_start + i;
            Q_local[i][j] = (gi < M) ? Q_global[gi][j] : 0.0;
        }
    }
}

// Store a tile of Q back to global memory
static void store_Q_tile(double Q_global[M][N], double Q_local[TILE_M][N], int row_start) {
    for (int i = 0; i < TILE_M; i++) {
#pragma HLS PIPELINE II=1
        for (int j = 0; j < N; j++) {
            int gi = row_start + i;
            if (gi < M) Q_global[gi][j] = Q_local[i][j];
        }
    }
}

extern "C" {

void kernel_gramschmidt(
    double A[M + 0][N + 0],
    double R[N + 0][N + 0],
    double Q[M + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=R offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=Q offset=slave bundle=gmem2
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=R bundle=control
#pragma HLS INTERFACE s_axilite port=Q bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Tiled local buffers: TILE_M x N strips instead of full M x N
    double A_tile[TILE_M][N];
    double Q_tile[TILE_M][N];
    double R_local[N][N];

#pragma HLS ARRAY_PARTITION variable=A_tile cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=Q_tile cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=R_local cyclic factor=8 dim=2

    // ------------------------------------------------------------------
    // PHASE 1: Gram-Schmidt with tiled loads/stores
    // ------------------------------------------------------------------
    // We iterate k over columns. For each k, we need to:
    //   (a) accumulate norm of A[:,k]  -- pass over all tiles
    //   (b) compute Q[:,k] = A[:,k] / nrm -- pass over all tiles
    //   (c) for each j>k: accumulate R[k][j] += Q[:,k] . A[:,j] -- pass over all tiles
    //   (d) for each j>k: update A[:,j] -= Q[:,k]*R[k][j]       -- pass over all tiles

    const int num_tiles = (M + TILE_M - 1) / TILE_M;

    // Initialize R to zero
    init_R_outer: for (int i = 0; i < N; i++) {
        init_R_inner: for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            R_local[i][j] = 0.0;
        }
    }

    for (int k = 0; k < N; k++) {

        // ------ Step (a): Compute norm of A[:,k] tiled ------
        double nrm = 0.0;
        norm_tile_loop: for (int t = 0; t < num_tiles; t++) {
            int row_start = t * TILE_M;

            // Load tile of A
            load_A_tile(A, A_tile, row_start);

            // Accumulate norm over this tile
            norm_inner: for (int i = 0; i < TILE_M; i++) {
#pragma HLS PIPELINE II=1
                int gi = row_start + i;
                if (gi < M) {
                    nrm += A_tile[i][k] * A_tile[i][k];
                }
            }
        }
        R_local[k][k] = sqrt(nrm);
        double rkk = R_local[k][k];

        // ------ Step (b): Compute Q[:,k] and store tiled ------
        q_tile_loop: for (int t = 0; t < num_tiles; t++) {
            int row_start = t * TILE_M;

            // Load tile of A (re-load for this pass)
            load_A_tile(A, A_tile, row_start);

            // Compute Q tile column k
            q_inner: for (int i = 0; i < TILE_M; i++) {
#pragma HLS PIPELINE II=1
                int gi = row_start + i;
                if (gi < M) {
                    Q_tile[i][k] = A_tile[i][k] / rkk;
                }
            }

            // Store Q tile back to global
            store_Q_tile(Q, Q_tile, row_start);
        }

        // ------ Steps (c) and (d): Update R and A for j > k ------
        update_j_loop: for (int j = k + 1; j < N; j++) {
            double rkj = 0.0;

            // (c) Accumulate R[k][j] tiled
            r_tile_loop: for (int t = 0; t < num_tiles; t++) {
                int row_start = t * TILE_M;

                // Load Q tile column k (need all columns for indexing)
                load_Q_tile(Q, Q_tile, row_start);

                // Load A tile
                load_A_tile(A, A_tile, row_start);

                // Accumulate R[k][j]
                r_inner: for (int i = 0; i < TILE_M; i++) {
#pragma HLS PIPELINE II=1
                    int gi = row_start + i;
                    if (gi < M) {
                        rkj += Q_tile[i][k] * A_tile[i][j];
                    }
                }
            }
            R_local[k][j] = rkj;

            // (d) Update A[:,j] tiled
            a_tile_loop: for (int t = 0; t < num_tiles; t++) {
                int row_start = t * TILE_M;

                // Load Q tile
                load_Q_tile(Q, Q_tile, row_start);

                // Load A tile
                load_A_tile(A, A_tile, row_start);

                // Update A tile column j
                a_inner: for (int i = 0; i < TILE_M; i++) {
#pragma HLS PIPELINE II=1
                    int gi = row_start + i;
                    if (gi < M) {
                        A_tile[i][j] = A_tile[i][j] - Q_tile[i][k] * rkj;
                    }
                }

                // Store updated A tile back
                store_A_tile(A, A_tile, row_start);
            }
        }
    }

    // ------------------------------------------------------------------
    // PHASE 2: Store R back to global memory
    // ------------------------------------------------------------------
    store_R_outer: for (int i = 0; i < N; i++) {
        store_R_inner: for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            R[i][j] = R_local[i][j];
        }
    }
}

} // extern "C"
```

**Key tiling changes made:**
1. **Smaller local buffers**: `A_tile[TILE_M][N]` and `Q_tile[TILE_M][N]` instead of full `[M][N]` — reduces BRAM usage per buffer from `M×N` to `TILE_M×N`
2. **Tile loop structure**: Each Gram-Schmidt step (norm, Q-compute, R-update, A-update) iterates over tiles `t = 0..num_tiles-1`
3. **Separate load/compute/store phases** via helper functions `load_A_tile`, `store_A_tile`, `load_Q_tile`, `store_Q_tile`
4. **Local compute**: All arithmetic operates on `A_tile` and `Q_tile` local buffers, not directly on global AXI memory
5. **TILE_M=16** chosen as a reasonable tile size (power of 2, fits in BRAM efficiently)

Looking at the current code, I need to apply pipeline optimization to the innermost compute loops. The key additions are:

1. `#pragma HLS PIPELINE II=1` on innermost loops (already present on some, need to verify all)
2. `#pragma HLS ARRAY_PARTITION` on local arrays for parallel access
3. `#pragma HLS DEPENDENCE` where loop-carried dependencies are false
4. `#pragma HLS LOOP_TRIPCOUNT` for variable-bound loops

The main issues I see:
- The `norm_inner`, `q_inner`, `r_inner`, `a_inner` loops access `A_tile[i][k]` and `Q_tile[i][k]` where `k` is the outer loop variable — these need column-dimension partitioning
- The accumulation loops (`nrm +=`, `rkj +=`) have loop-carried dependencies that are real (reductions), but we need `DEPENDENCE inter false` for the array accesses
- Variable-bound loops need `LOOP_TRIPCOUNT`

