Looking at the current code, I need to identify inner loops that can benefit from unrolling. The key candidates are:

1. **`norm_inner`**: 16 iterations, accumulates `A_tile[i][k]^2` - can unroll with reduction
2. **`q_inner`**: 16 iterations, computes `Q_tile[i][k] = A_tile[i][k] / rkk` - independent iterations
3. **`r_inner`**: 16 iterations, accumulates `Q_tile[i][k] * A_tile[i][j]` - reduction
4. **`a_inner`**: 16 iterations, updates `A_tile[i][j]` - independent iterations

The `TILE_M=16` loops all have 16 iterations. I'll use `factor=16` (complete unroll since dim=1 is already fully partitioned) or `factor=8` for partial unroll. Since `dim=1` is already `complete`, unrolling these loops fully makes sense. I'll use `UNROLL factor=16` for the TILE_M loops and also unroll the column loops (`N=80`) in load/store with factor=8, adjusting array partitioning to match.

```cpp
#include "gramschmidt.h"
#include <cmath>

#define TILE_M 16

// Load a tile of A rows [row_start, row_start+TILE_M) into local buffer
static void load_A_tile(double A_global[M][N], double A_local[TILE_M][N], int row_start) {
    for (int i = 0; i < TILE_M; i++) {
#pragma HLS PIPELINE II=1
        for (int j = 0; j < N; j++) {
#pragma HLS UNROLL factor=8
            int gi = row_start + i;
            A_local[i][j] = (gi < M) ? A_global[gi][j] : 0.0;
        }
    }
}

// Store a tile of A back to global memory
static void store_A_tile(double A_global[M][N], double A_local[TILE_M][N], int row_start) {
    for (int i = 0; i < TILE_M; i++) {
#pragma HLS PIPELINE II=1
        for (int j = 0; j < N; j++) {
#pragma HLS UNROLL factor=8
            int gi = row_start + i;
            if (gi < M) A_global[gi][j] = A_local[i][j];
        }
    }
}

// Load a tile of Q rows [row_start, row_start+TILE_M) into local buffer
static void load_Q_tile(double Q_global[M][N], double Q_local[TILE_M][N], int row_start) {
    for (int i = 0; i < TILE_M; i++) {
#pragma HLS PIPELINE II=1
        for (int j = 0; j < N; j++) {
#pragma HLS UNROLL factor=8
            int gi = row_start + i;
            Q_local[i][j] = (gi < M) ? Q_global[gi][j] : 0.0;
        }
    }
}

// Store a tile of Q back to global memory
static void store_Q_tile(double Q_global[M][N], double Q_local[TILE_M][N], int row_start) {
    for (int i = 0; i < TILE_M; i++) {
#pragma HLS PIPELINE II=1
        for (int j = 0; j < N; j++) {
#pragma HLS UNROLL factor=8
            int gi = row_start + i;
            if (gi < M) Q_global[gi][j] = Q_local[i][j];
        }
    }
}

