static void load_A_tile(MARS_WIDE_BUS_TYPE* A_global,
                         double A_local0[TILE_M][N],
                         double A_local1[TILE_M][N],
                         int row_start, int buf_sel) {
    if (buf_sel == 0) {
        for (int i = 0; i < TILE_M; i++) {
#pragma HLS PIPELINE II=1
            int gi = row_start + i;
            if (gi < M) {
                memcpy_wide_bus_read_double(A_local0[i], 0,
                    A_global, (gi * N) * sizeof(double),
                    sizeof(double) * N);
            } else {
                for (int j = 0; j < N; j++) {
#pragma HLS UNROLL factor=8
                    A_local0[i][j] = 0.0;
