The error is simply that `../../../common/mc.h` doesn't exist at that relative path. Since the wide bus types and helper functions aren't available via that header, I need to implement the coalescing manually using `ap_uint<512>` directly, defining the necessary types and helper functions inline.

```cpp
#include "gramschmidt.h"
#include <cmath>
#include <ap_int.h>
#include <string.h>

#define LARGE_BUS 512
typedef ap_uint<LARGE_BUS> MARS_WIDE_BUS_TYPE;

#define TILE_M 16

// 512-bit bus holds 8 doubles (8 * 64 = 512)
#define DOUBLES_PER_WORD 8

// Helper: read N doubles from wide bus global memory into local array
// src_byte_offset must be aligned to 512-bit (64-byte) boundary for best performance
static void wide_bus_read_row(double* dst, MARS_WIDE_BUS_TYPE* src, int row_idx, int num_cols) {
#pragma HLS INLINE
    int word_start = (row_idx * num_cols) / DOUBLES_PER_WORD;
    int num_words = (num_cols + DOUBLES_PER_WORD - 1) / DOUBLES_PER_WORD;
    for (int w = 0; w < num_words; w++) {
#pragma HLS PIPELINE II=1
        MARS_WIDE_BUS_TYPE word = src[word_start + w];
        for (int d = 0; d < DOUBLES_PER_WORD; d++) {
#pragma HLS UNROLL
            int col = w * DOUBLES_PER_WORD + d;
            if (col < num_cols) {
                ap_uint<64> bits = word.range(64*d + 63, 64*d);
                double val;
                memcpy(&val, &bits, sizeof(double));
                dst[col] = val;
            }
        }
    }
}

// Helper: write N doubles from local array into wide bus global memory
static void wide_bus_write_row(MARS_WIDE_BUS_TYPE* dst, int row_idx, double* src, int num_cols) {
#pragma HLS INLINE
    int word_start = (row_idx * num_cols) / DOUBLES_PER_WORD;
    int num_words = (num_cols + DOUBLES_PER_WORD - 1) / DOUBLES_PER_WORD;
    for (int w = 0; w < num_words; w++) {
#pragma HLS PIPELINE II=1
        MARS_WIDE_BUS_TYPE word = 0;
        for (int d = 0; d < DOUBLES_PER_WORD; d++) {
#pragma HLS UNROLL
            int col = w * DOUBLES_PER_WORD + d;
            if (col < num_cols) {
                double val = src[col];
                ap_uint<64> bits;
                memcpy(&bits, &val, sizeof(double));
                word.range(64*d + 63, 64*d) = bits;
            }
        }
        dst[word_start + w] = word;
    }
}

// Load a tile of A rows [row_start, row_start+TILE_M) into local buffer (double-buffered)
static void load_A_tile(MARS_WIDE_BUS_TYPE* A_global,
                         double A_local0[TILE_M][N],
